<script>
 import PowerTrend from "./PowerTrend.svelte";
 import {usePresentation} from "$lib/presentation.svelte.js";
 import SimulationNotice from "./SimulationNotice.svelte";
 import {page} from '$app/state';import AdminNotice from './AdminNotice.svelte';import Icon from './Icon.svelte';import EnergyFlow from './EnergyFlow.svelte';import BatteryGauge from './BatteryGauge.svelte';import HistoryChart from './HistoryChart.svelte';import {connectionLabel} from '$lib/admin-domain';import {formatValue,formatTime} from '$lib/energy';
 let {data:incoming,form=null}=$props();
 const presentation=usePresentation(()=>incoming);let data=$derived(presentation.data);
const tabs=['overview','history','equipment','connection','access','activity'];let tab=$derived(tabs.includes(page.url.searchParams.get('tab'))?page.url.searchParams.get('tab'):'overview');
 let node=$derived(data.node);let connection=$derived(data.connections.find(c=>c.node_id===node.id));let hasToken=$derived(data.secrets.some(s=>s.node_id===node.id));let label=$derived(connectionLabel(connection,hasToken));let snapshot=$derived(data.snapshots.find(s=>s.node_id===node.id));let metrics=$derived(snapshot?.measurements||{});let check=$derived(data.check);let checkMetrics=$derived(check?.result?.snapshot?.metrics||{});
 let assigned=$derived(data.memberships.filter(m=>m.node_id===node.id));
 let history=$derived.by(()=>{const result={solar:[],consumption:[]};for(const metric of ['solar','consumption'])result[metric]=(data.intervals||[]).filter(r=>r.metric===metric).map(r=>({time:r.interval_start,value:Number(r.energy_kwh)}));return result;});
 const date=value=>value?new Intl.DateTimeFormat('en-ZW',{timeZone:'Africa/Harare',dateStyle:'medium',timeStyle:'short'}).format(new Date(value)):'Not yet';
</script>
{#if data.simulated}<SimulationNotice/>{/if}
<a class="admin-back" href="/admin/nodes">← All energy nodes</a><div class="admin-page-heading"><div><span class="admin-eyebrow">{node.reference} · {node.location_label}</span><h1>{node.display_name}</h1><p>{data.communities.find(c=>c.id===node.community_id)?.name||'Community not assigned'} · {data.simulated?'Solar & storage':'SunSynk solar & storage'}</p></div><span class="admin-status" class:good={label==='Verified'}>{label}</span></div><AdminNotice {form}/>
<nav class="admin-detail-tabs" aria-label="Node details">{#each tabs as key}<a href={`?tab=${key}`} class:active={tab===key} aria-current={tab===key?'page':undefined}>{key[0].toUpperCase()+key.slice(1)}</a>{/each}</nav>
{#if tab==='overview'}
 <div class="admin-node-summary"><div><span>Connection</span><strong>{label}</strong></div><div><span>Assigned clients</span><strong>{assigned.length}</strong></div><div><span>{data.simulated?'Updated at':'Last measured reading'}</span><strong>{date(snapshot?.reported_at)}</strong></div><div><span>Latest collection</span><strong>{date(connection?.last_sync_at)}</strong></div></div>
 {#if !data.simulated&&!connection?.verified_at}<div class="admin-notice"><strong>Finish the connection before live monitoring.</strong><p>Registering a node does not validate its readings. Select its installation, test the data and complete the VRM comparison.</p><a class="admin-button" href="?tab=connection">Set up connection →</a></div>{/if}
 <div class="admin-two-column"><section class="admin-panel"><div class="admin-panel-head"><div><span class="admin-eyebrow">{data.simulated?'CURRENT POWER':'LATEST STORED MEASUREMENTS'}</span><h2>Your connected energy system</h2></div></div><EnergyFlow {metrics} simulated={data.simulated}/></section><BatteryGauge {metrics}/></div>
 {#if data.simulated}<PowerTrend reportedAt={snapshot?.reported_at}/>{/if}
 <section class="admin-panel"><div class="admin-panel-head"><div><span class="admin-eyebrow">NODE REGISTRATION</span><h2>Residence & community</h2></div></div><form method="POST" class="admin-form-grid"><input type="hidden" name="operation" value="node.save"/><input type="hidden" name="node_id" value={node.id}/><label>Display name<input name="display_name" value={node.display_name} required minlength="2" maxlength="120"/></label><label>Location label<input name="location_label" value={node.location_label} required maxlength="120"/></label><label>Community<select name="community_id" value={node.community_id||''}><option value="">Not assigned</option>{#each data.communities as c}<option value={c.id}>{c.name}</option>{/each}</select></label><button class="admin-button">Save registration</button></form></section>
<section class="admin-panel"><div class="admin-panel-head"><div><span class="admin-eyebrow">COMMUNITY SATELLITE MAP</span><h2>Node coordinates</h2></div><a class="admin-text-link" href="/admin/communities">View community map</a></div><p class="admin-help">Enter the verified GPS location in decimal degrees. Southern latitudes are negative. Leave both fields blank to remove the location. Do not use example coordinates for an actual residence.</p><form method="POST" class="admin-form-grid"><input type="hidden" name="operation" value="node.location"/><input type="hidden" name="node_id" value={node.id}/><label>Latitude<input type="number" name="latitude" step="any" min="-90" max="90" value={node.latitude??''} placeholder="-17.00000"/></label><label>Longitude<input type="number" name="longitude" step="any" min="-180" max="180" value={node.longitude??''} placeholder="31.00000"/></label><button class="admin-button">Save coordinates</button></form></section>
{:else if tab==='connection'&&data.simulated}
<section class="admin-panel"><span class="admin-eyebrow">ENERGY CONNECTION</span><h2>Your prototype workspace is connected.</h2><p class="admin-help">Explore changing solar production, household demand, battery charging and grid support in the overview. Both portals follow the same energy scenario.</p><a class="admin-button" href="?tab=overview">View energy system</a></section>
{:else if tab==='connection'}
 <div class="admin-connection-steps"><div class:done={hasToken}><span>01</span><strong>Secure token</strong><small>{hasToken?'Encrypted and stored':'Not configured'}</small></div><div class:done={connection?.provider_installation_id}><span>02</span><strong>Select installation</strong><small>{connection?.provider_installation_id?'ID '+connection.provider_installation_id:'Selection needed'}</small></div><div class:done={check?.result?.ready&&check.revision===connection?.revision}><span>03</span><strong>Test readings</strong><small>{connection?.last_test_status||'Test needed'}</small></div><div class:done={connection?.verified_at}><span>04</span><strong>Verify & collect</strong><small>{connection?.verified_at?'Verified':'Comparison needed'}</small></div></div>
 <div class="admin-two-column"><section class="admin-panel"><div class="admin-panel-head"><div><span class="admin-eyebrow">01 · SERVER-ONLY CREDENTIAL</span><h2>{hasToken?'Replace access token':'Add access token'}</h2></div><Icon name="lock"/></div><p class="admin-help">{hasToken?'A token is stored securely. It cannot be displayed here. Replacing it resets verification.':'Enter the VRM access token. It will be validated and encrypted before storage.'}</p><form method="POST" class="admin-stacked-form"><input type="hidden" name="operation" value="connection.token"/>{@render connectionFields()}<label>SunSynk access token<input type="password" name="token" required maxlength="8192" autocomplete="new-password" placeholder={hasToken?'Enter replacement token':'Enter access token'}/></label><button class="admin-button">{hasToken?'Validate & replace token':'Validate & save token'}</button></form><p class="admin-help">No provider token is sent to the client's browser. Provider requests remain GET-only.</p></section>
 <section class="admin-panel"><div class="admin-panel-head"><div><span class="admin-eyebrow">02 · MATCH THE PHYSICAL SITE</span><h2>Select its VRM installation</h2></div></div><p class="admin-help">Your GridUbuntu display name can differ from the VRM site name. Select the actual installation belonging to this residence; its provider ID is saved automatically.</p><div class="admin-key-value"><span>Selected installation</span><strong>{connection?.provider_installation_id||'None selected'}</strong></div><form method="POST"><input type="hidden" name="operation" value="connection.discover"/>{@render connectionFields()}<button class="admin-button secondary" disabled={!hasToken}>Find accessible installations →</button></form>{#if form?.sites&&form.nodeId===node.id}<form method="POST" class="admin-stacked-form"><input type="hidden" name="operation" value="connection.select"/>{@render connectionFields()}<label>Installation<select name="installation_id" required><option value="">Select the correct site</option>{#each form.sites as site}<option value={site.id}>{site.name} · {site.id}</option>{/each}</select></label><button class="admin-button">Assign selected installation</button></form>{/if}<p class="admin-help">A node with measured history cannot be reassigned to a different installation. Register a new node to preserve accurate provenance.</p></section></div>
 <section class="admin-panel"><div class="admin-panel-head"><div><span class="admin-eyebrow">03 · CHECK BEFORE COMMISSIONING</span><h2>Test provider readings</h2></div><form method="POST"><input type="hidden" name="operation" value="connection.check"/>{@render connectionFields()}<button class="admin-button secondary" disabled={!hasToken||!connection?.provider_installation_id||!connection?.active}>Run read-only test →</button></form></div>{#if check}<div class="admin-notice" class:failure={!check.result.ready}><strong>{check.result.ready?'Core measurements are available':'Readings need review'}</strong><p>Tested {date(check.tested_at)} · connection revision {check.revision}. Verification needs current solar, household consumption, battery charge and energy totals. Compare values and units with the VRM dashboard.</p></div><div class="admin-table-scroll"><table class="admin-table"><thead><tr><th>Measurement</th><th>Provider value</th><th>Reporting time · CAT</th><th>Source path</th></tr></thead><tbody>{#each [['solar','Solar power','W'],['consumption','Household load','W'],['batterySoc','Battery charge','%'],['batteryPower','Battery power','W'],['batteryVoltage','Battery voltage','V'],['grid','Grid power','W']] as [key,title,unit]}<tr><th scope="row">{title}</th><td>{formatValue(checkMetrics[key]?.value,unit,2)}</td><td>{date(checkMetrics[key]?.reportedAt)}</td><td><code>{checkMetrics[key]?.source||'Not reported'}</code></td></tr>{/each}</tbody></table></div><div class="admin-test-totals"><span>Solar generated today <strong>{formatValue(check.result.totals?.solar,'kWh',2)}</strong></span><span>Consumed today <strong>{formatValue(check.result.totals?.consumption,'kWh',2)}</strong></span></div>{:else}<div class="admin-empty"><Icon name="system" size={30}/><strong>No connection test yet</strong><p>Select an installation, then retrieve its current reported measurements.</p></div>{/if}</section>
 <div class="admin-two-column"><section class="admin-panel"><span class="admin-eyebrow">04 · HUMAN VERIFICATION</span><h2>Confirm the VRM comparison</h2><form method="POST" class="admin-stacked-form"><input type="hidden" name="operation" value="connection.commission"/>{@render connectionFields()}<label>Verification notes<textarea name="notes" required minlength="10" maxlength="1000" rows="3" placeholder="Record the VRM values, units and time you compared."></textarea></label><label class="admin-checkbox"><input type="checkbox" name="confirmed" value="yes" required/>I compared this installation's reported values and units with VRM and confirmed that it belongs to this residence.</label><button class="admin-button" disabled={!check?.result?.ready||check.revision!==connection?.revision}>Verify connection</button></form><p class="admin-help">A successful test must be less than 30 minutes old. Verification authorizes client display and scheduled history collection.</p></section><section class="admin-panel"><span class="admin-eyebrow">COLLECTION & CONNECTION ACCESS</span><h2>Operational actions</h2><div class="admin-key-value"><span>Verified at</span><strong>{date(connection?.verified_at)}</strong></div><div class="admin-key-value"><span>Last collection</span><strong>{date(connection?.last_sync_at)}</strong></div><form method="POST"><input type="hidden" name="operation" value="connection.sync"/>{@render connectionFields()}<button class="admin-button" disabled={!connection?.verified_at||!connection?.active}>Collect measured data now →</button></form><form method="POST"><input type="hidden" name="operation" value="connection.pause"/>{@render connectionFields()}<button class="admin-button secondary" disabled={!connection?.active}>Pause monitoring</button></form><details class="admin-row-details"><summary>Remove stored credential</summary><form method="POST" class="admin-stacked-form"><input type="hidden" name="operation" value="connection.remove"/>{@render connectionFields()}<label class="admin-checkbox"><input type="checkbox" name="confirmed" value="yes" required/>Remove the encrypted credential and pause monitoring. Keep measured history.</label><button class="admin-button danger" disabled={!hasToken}>Remove credential</button></form></details></section></div>
{:else if tab==='access'}
 <section class="admin-panel"><div class="admin-panel-head"><div><span class="admin-eyebrow">RESIDENCE MEMBERSHIP</span><h2>Assigned clients</h2></div></div>{#each assigned as member}{@const client=data.clients.find(c=>c.id===member.user_id)}<div class="admin-member-row"><span class="admin-avatar">{(client?.full_name||'Client').slice(0,2).toUpperCase()}</span><div><strong>{client?.full_name||'Client'}</strong><p>{client?.email||'Email unavailable'} · {client?.active?'Access active':'Access revoked'}</p></div><form method="POST"><input type="hidden" name="operation" value="membership.remove"/><input type="hidden" name="node_id" value={node.id}/><input type="hidden" name="user_id" value={member.user_id}/><button class="admin-button secondary">Remove assignment</button></form></div>{/each}{#if !assigned.length}<div class="admin-empty">No clients are assigned to this node.</div>{/if}<form method="POST" class="admin-inline-form"><input type="hidden" name="operation" value="membership.add"/><input type="hidden" name="node_id" value={node.id}/><label>Add an invited client<select name="user_id" required><option value="">Select client</option>{#each data.clients.filter(c=>c.role==='client'&&!assigned.some(m=>m.user_id===c.id)) as client}<option value={client.id}>{client.full_name} · {client.email}</option>{/each}</select></label><button class="admin-button">Assign client →</button></form><p class="admin-help">Assignments grant read-only access to this residence. Removing a membership revokes its data access without deleting the account.</p></section>
{:else if tab==='history'}
 <section class="admin-panel"><div class="admin-panel-head"><div><span class="admin-eyebrow">{data.simulated?'ENERGY HISTORY':'PERSISTED MEASUREMENTS'}</span><h2>Generation & consumption</h2></div><a class="admin-text-link" href={'/admin/history?node='+node.id}>History & export →</a></div><div class="admin-range-tabs">{#each [['today','Today'],['7d','7 days'],['30d','30 days']] as [value,title]}<a href={`?tab=history&range=${value}`} class:active={data.range===value}>{title}</a>{/each}</div><HistoryChart {history} range={data.range||'7d'}/></section>
{:else if tab==='equipment'}
 <section class="admin-panel"><div class="admin-panel-head"><div><span class="admin-eyebrow">{data.simulated?'SYSTEM EQUIPMENT':'REPORTED BY VRM'}</span><h2>Connected devices</h2></div></div>{#each data.simulated?data.simulatedDevices:check?.result?.devices||[] as device}<div class="admin-device-row"><Icon name="system" size={25}/><div><strong>{device.name}</strong><p>{device.firmware?'Firmware '+device.firmware:'Firmware not reported'}</p></div></div>{/each}{#if !data.simulated&&!check?.result?.devices?.length}<div class="admin-empty"><strong>Equipment details are not available yet</strong><p>Run a connection test to retrieve the installation's reported equipment.</p></div>{/if}</section>
{:else if tab==='activity'}
 <section class="admin-panel"><div class="admin-panel-head"><div><span class="admin-eyebrow">NODE-SPECIFIC AUDIT TRAIL</span><h2>Administrative activity</h2></div></div><div class="admin-table-scroll"><table class="admin-table"><thead><tr><th>Time · CAT</th><th>Action</th><th>Administrator</th></tr></thead><tbody>{#each data.activity||[] as event}<tr><td>{date(event.created_at)}</td><td>{event.action.replaceAll('.',' / ').replaceAll('_',' ')}</td><td>{data.clients.find(c=>c.id===event.actor_id)?.full_name||'System / setup'}</td></tr>{/each}{#if !data.activity?.length}<tr><td colspan="3"><div class="admin-empty">No events recorded for this node yet.</div></td></tr>{/if}</tbody></table></div></section>
{/if}
{#snippet connectionFields()}<input type="hidden" name="node_id" value={node.id}/><input type="hidden" name="revision" value={connection?.revision||1}/>{/snippet}
